using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Imports messages exported from another app
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> ImportMessagesAsync(long chatId = default, InputFile messageFile = default, InputFile[] attachedFiles = default)
    {

           using var activity =  StartCallActivity("ImportMessagesAsync", typeof(ImportMessages).FullName ?? "ImportMessagesAsync");

           try
           {
             return client.ImportMessagesAsync(chatId, messageFile, attachedFiles);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
